<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';
const props=defineProps<{screen:string;api:(path:string,method?:string,body?:any)=>Promise<any>}>();
const records=ref<any[]>([]),notice=ref(''),busy=ref(false),system=ref(''),client=ref(''),entry=ref(''),redirects=ref(''),secret=ref(''),protocol=ref('OIDC'),plan=ref(''),evidence=ref('');
const checks=ref({login:false,callback:false,permission:false,revocation:false,isolation:false});
const review=ref<any>(null),reason=ref(''),actor=ref(''),from=ref(''),until=ref(''),archived=ref(false),kind=ref(''),page=ref(0),total=ref(0),target=ref(''),department=ref('');
async function run(fn:()=>Promise<void>){busy.value=true;notice.value='';try{await fn()}catch(e){notice.value=(e as Error).message}finally{busy.value=false}}
async function load(){let path='';switch(props.screen){case 'access':path='/api/platform/applications';break;case 'reviews':path='/api/platform/reviews/candidates?page='+page.value;break;case 'reviewhistory':path='/api/platform/reviews?page='+page.value;break;case 'syncfailures':path='/api/platform/sync/failures';break;case 'notifications':path='/api/platform/notifications';break;case 'administrators':path='/api/platform/administrators';break;case 'orgread':{const data=await props.api('/api/platform/organization/read-only');records.value=[...data.departments.map((x:any)=>({...x,category:'部门'})),...data.posts.map((x:any)=>({...x,category:'岗位'})),...data.dictionary.map((x:any)=>({...x,category:'字典'}))];return;}case 'auditsearch':{const q=new URLSearchParams({archived:String(archived.value),page:String(page.value),size:'25'});if(actor.value)q.set('actorId',actor.value);if(kind.value)q.set('kind',kind.value);if(from.value)q.set('from',new Date(from.value).toISOString());if(until.value)q.set('until',new Date(until.value).toISOString());path='/api/platform/audit/search?'+q;break;}}
if(path){const data=await props.api(path);records.value=Array.isArray(data)?data:data.items;total.value=data.total||records.value.length;}}
async function configure(){await run(async()=>{await props.api(`/api/platform/applications/${Number(system.value)}/config`,'PUT',{clientId:client.value,entryUrl:entry.value,protocol:protocol.value,redirectUris:redirects.value.split('\n').map(x=>x.trim()).filter(Boolean),clientSecret:secret.value||null,compatibilityPlan:plan.value||null});secret.value='';await load();notice.value='配置已保存，验收通过后才会启用。';});}
async function edit(row:any){await run(async()=>{const c=await props.api(`/api/platform/applications/${row.system_id}/config`);system.value=String(c.system_id);client.value=c.client_id;entry.value=c.entry_url;protocol.value=c.protocol;redirects.value=c.redirectUris.join('\n');plan.value=c.compatibility_plan||'';secret.value='';checks.value={login:false,callback:false,permission:false,revocation:false,isolation:false};evidence.value='';});}
async function accept(){await run(async()=>{await props.api(`/api/platform/applications/${Number(system.value)}/acceptance`,'POST',{...checks.value,evidence:evidence.value});await load();notice.value='已保存接入验收记录。';});}
async function decide(decision:string){await run(async()=>{await props.api('/api/platform/reviews','POST',{userId:review.value.user_id,roleId:review.value.role_id,decision,reason:reason.value});review.value=null;reason.value='';await load();notice.value='复核结论已记录。';});}
async function resolve(row:any){const value=prompt('填写异常原因、修复措施或替代请求编号');if(!value)return;await run(async()=>{await props.api(`/api/platform/sync/failures/${row.id}/resolve`,'POST',{reason:value});await load();});}
async function membership(grant:boolean){if(!confirm('确认变更超级管理员成员？目标账号的现有会话将失效。'))return;await run(async()=>{await props.api(`/api/platform/super-administrators/${Number(target.value)}`,'PUT',{administrator:grant});await load();});}
async function bind(remove:boolean){await run(async()=>{await props.api(`/api/platform/administrators/${Number(target.value)}`+(remove?'/'+Number(department.value):''),remove?'DELETE':'PUT',remove?undefined:{departmentId:Number(department.value)});await load();});}
onMounted(()=>run(load));watch(()=>props.screen,()=>{records.value=[];review.value=null;page.value=0;void run(load)});
</script>
<template>
 <section><p v-if="notice" role="status" class="notice">{{notice}}</p><button :disabled="busy" @click="run(load)">刷新记录</button>
 <template v-if="screen==='access'">
 <form class="editor" @submit.prevent="configure"><h2>应用接入配置</h2><p>先在应用管理中注册业务系统，再填写接入配置。配置变更后需要重新验收。</p><div class="form-grid">
 <label>业务系统编号<input v-model="system" type="number" min="1" required></label><label>客户端编号<input v-model="client" required maxlength="100"></label>
 <label>应用入口<input v-model="entry" type="url" required maxlength="2048"></label><label>接入方式<select v-model="protocol"><option>OIDC</option><option value="LEGACY">暂不能改造，隔离接入</option></select></label>
 <label v-if="protocol==='OIDC'">回调地址，每行一个<textarea v-model="redirects" required rows="3"/></label><label v-if="protocol==='OIDC'">客户端密钥，留空保留原配置<input v-model="secret" type="password" autocomplete="new-password" minlength="32"></label>
 <label v-if="protocol==='LEGACY'">兼容与隔离方案<textarea v-model="plan" required maxlength="2000" rows="3"/></label></div><button class="primary" :disabled="busy">保存配置</button></form>
 <form class="editor" @submit.prevent="accept"><h2>接入验收</h2><p>以下结果由验收人员实际确认后填写；保存配置本身不代表验收通过。</p><label v-for="(label,key) in {login:'已验证登录与免登',callback:'已验证精确回调及错误回调拒绝',permission:'已验证授权与无权限拒绝',revocation:'已验证权限回收或账号停用',isolation:'已确认应用隔离与访问边界'}" :key="key" class="checkbox"><input v-model="checks[key]" type="checkbox">{{label}}</label><label>验收证据和说明<textarea v-model="evidence" required maxlength="1500" rows="3"/></label><button :disabled="busy||!system">记录验收结果</button></form>
 </template>
 <form v-if="screen==='auditsearch'" class="editor" @submit.prevent="page=0;run(load)"><div class="form-grid"><label>操作人编号<input v-model="actor" type="number" min="1"></label><label>事件类型<input v-model="kind"></label><label>开始时间<input v-model="from" type="datetime-local"></label><label>结束时间<input v-model="until" type="datetime-local"></label></div><label class="checkbox"><input v-model="archived" type="checkbox">查询归档记录</label><button :disabled="busy">查询</button></form>
 <form v-if="screen==='administrators'" class="editor" @submit.prevent="bind(false)"><label>目标用户编号<input v-model="target" required type="number" min="1"></label><label>管辖部门编号<input v-model="department" type="number" min="1"></label><div class="actions"><button :disabled="busy||!department">任命部门管理员</button><button type="button" :disabled="busy||!department" @click="bind(true)">解除部门绑定</button><button type="button" :disabled="busy||!target" @click="membership(true)">授予超级管理员</button><button type="button" :disabled="busy||!target" @click="membership(false)">解除超级管理员</button></div></form>
 <form v-if="review" class="editor" @submit.prevent="decide('KEEP')"><h2>复核 {{review.username}} 的 {{review.role_name}}</h2><label>复核理由<textarea v-model="reason" required maxlength="1000"/></label><div class="actions"><button :disabled="busy">确认保留</button><button type="button" :disabled="busy||!reason.trim()" @click="decide('REVOKE')">回收角色并记录</button></div></form>
 <div class="table-wrap"><table v-if="records.length"><thead><tr><th v-for="key in Object.keys(records[0])" :key="key">{{({system_id:'系统编号',client_id:'客户端',entry_url:'入口',protocol:'方式',status:'状态',compatibility_plan:'兼容方案',acceptance:'验收证据',name:'名称',user_id:'用户',username:'账号',role_id:'角色',role_name:'角色名',decision:'结论',reason:'理由',actor_id:'操作人',created_at:'时间',source:'来源',request_id:'请求编号',error:'错误',resolution:'处理记录',message:'消息',department_id:'部门',administrator:'超级管理员',built_in_administrator:'内置管理员',kind:'类型',result:'结果',target:'对象',archived_at:'归档时间',id:'编号'} as Record<string,string>)[key]||key}}</th><th v-if="['access','reviews','syncfailures'].includes(screen)">操作</th></tr></thead><tbody><tr v-for="(row,i) in records" :key="i"><td v-for="key in Object.keys(records[0])" :key="key">{{row[key]??'—'}}</td><td v-if="screen==='access'"><button @click="edit(row)">配置</button></td><td v-if="screen==='reviews'"><button @click="review=row;reason=''">复核</button></td><td v-if="screen==='syncfailures'"><button v-if="row.status==='OPEN'" @click="resolve(row)">记录处理结果</button></td></tr></tbody></table><p v-else>暂无记录。</p></div>
 <div v-if="['auditsearch','reviews','reviewhistory'].includes(screen)" class="actions"><button :disabled="page===0||busy" @click="page--;run(load)">上一页</button><span>共 {{total}} 条，第 {{page+1}} 页</span><button :disabled="(page+1)*(screen==='auditsearch'?25:100)>=total||busy" @click="page++;run(load)">下一页</button></div>
 </section>
</template>
